import React, { useEffect, useMemo, useRef, useState } from 'react';
import { BackHandler, Linking, Modal, Platform, Pressable, ScrollView, StyleSheet, TextInput, View, useWindowDimensions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import Svg, { Path, Circle } from 'react-native-svg';
import { Text } from '@/components/ui/sl-text';
import { AnalyticalTimeSeriesChart } from '@/components/charts/AnalyticalTimeSeriesChart';
import { analyticalMetricDefinition } from '@/lib/chart-fidelity';
import { estimateMovementStrengthKg, strengthMetricForMovementClass } from '@/lib/movement-strength-metric';
import { resolvePlateClubState, strengthTierState, totalStrengthClubName } from '@/lib/ledger-rewards';
import { deriveVolumeAchievement, deriveVolumeComparisonPresentation, type VolumeAchievementContextId } from '@/lib/volume-achievements';
import { strengthTierCertificationFixture } from '@/dev-mocks/fixtures/strength-tier';
import { LEDGER_STUDY as T } from '@/constants/ledger-study';
import { STUDY_SESSION_DETAILS, STUDY_CORE_DETAILS, STUDY_HISTORY, STUDY_MOVEMENTS, STUDY_TOUR, studyImprovement, studyWeight, type StudyFamily, type StudyMovement, type StudyScene, type StudyTab, type StudyUnit } from '@/dev-mocks/fixtures/ledger-study';

const C = T.colors;
type IconName = keyof typeof Ionicons.glyphMap;
type Sheet = 'set' | 'search' | 'guide' | 'method' | 'tiers' | 'volume' | null;
type SetEvidence = { name: string; kg: number; reps: number; rpe: number; date: string; session: string; note: string; previousKg: number | null; assisted: boolean; equipment: string };
function fullDate(value: string) { return new Date(value + 'T12:00:00Z').toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' }); }
const TAB_LABELS: Record<StudyTab, string> = { records: 'Records', history: 'History', milestones: 'Milestones' };
const REFERENCES = [
  { title: 'Apple · Navigation', url: 'https://developer.apple.com/design/human-interface-guidelines/tab-bars', note: 'Keep destinations predictable and their current state visible.' },
  { title: 'Apple · Charts', url: 'https://developer.apple.com/design/human-interface-guidelines/charts', note: 'Lead with the meaning. Keep labels, units and inspectable evidence.' },
  { title: 'Linear · UI redesign', url: 'https://linear.app/now/how-we-redesigned-the-linear-ui', note: 'Reduce competing chrome; test complete flows and information density.' },
  { title: 'Oura · Trends', url: 'https://support.ouraring.com/hc/en-us/articles/360055983614-Using-Trends', note: 'Pair a current value with a clearly defined historical range.' },
  { title: 'Hevy · Exercise history', url: 'https://www.hevyapp.com/features/track-exercises/', note: 'Make exact exercise history a direct, familiar destination.' },
] as const;

function Icon({ name, color = C.secondary, size = 20 }: { name: IconName; color?: string; size?: number }) { return <Ionicons name={name} color={color} size={size} />; }
function Eyebrow({ children, color = C.muted }: React.PropsWithChildren<{ color?: string }>) { return <Text style={[s.eyebrow, { color }]}>{children}</Text>; }
function Button({ label, onPress, quiet = false, icon, testID }: { label: string; onPress: () => void; quiet?: boolean; icon?: IconName; testID?: string }) {
  return <Pressable testID={testID} accessibilityRole="button" accessibilityLabel={label} onPress={onPress} style={({ pressed }) => [s.button, quiet && s.quietButton, pressed && s.pressed]}><Text style={[s.buttonText, quiet && s.quietButtonText]}>{label}</Text>{icon ? <Icon name={icon} color={quiet ? C.text : C.onAction} size={18} /> : null}</Pressable>;
}
function IconButton({ label, onPress, name }: { label: string; onPress: () => void; name: IconName }) { return <Pressable accessibilityRole="button" accessibilityLabel={label} onPress={onPress} style={({ pressed }) => [s.iconButton, pressed && s.pressed]}><Icon name={name} /></Pressable>; }
function Section({ title, detail, action, onPress }: { title: string; detail?: string; action?: string; onPress?: () => void }) { return <View style={s.sectionHeading}><View style={s.flex}><Text style={s.sectionTitle}>{title}</Text>{detail ? <Text style={s.caption}>{detail}</Text> : null}</View>{action && onPress ? <Pressable accessibilityRole="button" accessibilityLabel={action} onPress={onPress} style={s.textAction}><Text style={s.actionText}>{action}</Text><Icon name="arrow-forward" size={15} /></Pressable> : null}</View>; }
function Spark({ color, values = [18, 23, 21, 29, 26, 38, 35, 43] }: { color: string; values?: readonly number[] }) { return <Svg width={66} height={32} viewBox="0 0 66 44" accessible={false}><Path d={values.map((v, i) => `${i ? 'L' : 'M'} ${i * 9} ${46 - v}`).join(' ')} stroke={color} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" fill="none" /><Circle cx={63} cy={46 - values[values.length - 1]} r={2.5} fill={color} /></Svg>; }
function tone(m: StudyMovement) { return m.parent ? C[m.parent] : C.teal; }
function Load({ kg, unit, reps, large = false, assistance = false, compact = false }: { kg: number; unit: StudyUnit; reps?: number; large?: boolean; assistance?: boolean; compact?: boolean }) { return <View style={s.loadLine}><Text style={compact ? s.compactNumber : large ? s.heroNumber : s.loadNumber}>{studyWeight(kg, unit)}</Text><Text style={large && !compact ? s.heroUnit : s.loadUnit}>{unit}{assistance ? ' assistance' : ''}{reps ? ` × ${reps}` : ''}</Text></View>; }
function FamilyPicker({ value, onChange }: { value: StudyFamily; onChange: (f: StudyFamily) => void }) { return <View accessibilityRole="tablist" style={s.familyRow}>{(['core', 'variants', 'accessories'] as const).map(f => <Pressable testID={`study-family-${f}`} key={f} accessibilityRole="tab" accessibilityState={{ selected: value === f }} aria-selected={value === f} onPress={() => onChange(f)} style={[s.family, f === value && s.familySelected]}><Text style={[s.familyText, f === value && s.familyTextSelected]}>{f === 'core' ? 'Core lifts' : f === 'variants' ? 'Variants' : 'Accessories'}</Text></Pressable>)}</View>; }
function MovementRow({ m, unit, onPress }: { m: StudyMovement; unit: StudyUnit; onPress: () => void }) { return <Pressable accessibilityRole="button" accessibilityLabel={`Open ${m.name}, ${m.equipment}, ${studyWeight(m.kg, unit)} ${unit}${m.assisted ? " assistance" : ""} for ${m.reps} repetitions`} onPress={onPress} style={({ pressed }) => [s.movementRow, pressed && s.pressed]}><View style={[s.liftMark, { backgroundColor: tone(m) }]} /><View style={s.flex}><Text style={s.rowTitle}>{m.shortName}</Text><Text style={s.caption}>{m.family === 'core' ? `Best logged single · ${m.date}` : m.equipment}</Text><View style={s.rowLoad}><Load kg={m.kg} unit={unit} reps={m.reps} assistance={m.assisted} />{m.baseline ? <Text style={s.caption}>First set</Text> : null}</View></View>{m.family === 'core' ? <Spark color={tone(m)} /> : null}<Icon name="chevron-forward" color={C.muted} size={17} /></Pressable>; }
function LinkRow({ title, detail, name, onPress, right }: { title: string; detail: string; name: IconName; onPress: () => void; right?: string }) { return <Pressable accessibilityRole="button" onPress={onPress} accessibilityLabel={title} style={({ pressed }) => [s.linkRow, pressed && s.pressed]}><View style={s.smallIcon}><Icon name={name} size={20} /></View><View style={s.flex}><Text style={s.rowTitle}>{title}</Text><Text style={s.caption}>{detail}</Text></View>{right ? <Text style={s.caption}>{right}</Text> : null}<Icon name="chevron-forward" color={C.muted} size={17} /></Pressable>; }
function Empty({ icon, title, body }: { icon: IconName; title: string; body: string }) { return <View style={s.empty}><View style={s.emptyIcon}><Icon name={icon} size={30} color={C.accent} /></View><Text style={s.emptyTitle}>{title}</Text><Text style={s.emptyCopy}>{body}</Text></View>; }

export default function LedgerDesignStudy({ embedded = false, onExit }: { embedded?: boolean; onExit?: () => void }) {
  const dimensions = useWindowDimensions();
  const desktop = !embedded && dimensions.width >= 1080;
  const [scene, setScene] = useState<StudyScene>('record');
  const [tab, setTab] = useState<StudyTab>('records');
  const [family, setFamily] = useState<StudyFamily>('core');
  const [unit, setUnit] = useState<StudyUnit>('kg');
  const [movementId, setMovementId] = useState('example-squat');
  const [range, setRange] = useState<'6w' | '12w' | 'all'>('12w');
  const [metric, setMetric] = useState<'top' | 'five'>('top');
  const [sheet, setSheet] = useState<Sheet>(null);
  const [query, setQuery] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const savedScenes = useRef<Record<StudyTab, StudyScene>>({ records: 'record', history: 'history', milestones: 'milestones' });
  const [historyFilter, setHistoryFilter] = useState<'all' | 'prs'>('all');
  const [sessionId, setSessionId] = useState<string>(STUDY_HISTORY[0].id);
  const [firstWeek, setFirstWeek] = useState(false);
  const [evidence, setEvidence] = useState<SetEvidence>({ assisted: false, equipment: 'Barbell', name: 'Competition Squat', kg: 170, reps: 5, rpe: 8, date: 'October 28, 2026', session: 'Lower · Week 4', note: '5-rep best', previousKg: 165 as number | null });
  const scroll = useRef<ScrollView>(null), offsets = useRef<Record<string, number>>({});
  const location = `${scene}:${family}:${movementId}`;
  const selectedMovement = STUDY_MOVEMENTS.find(m => m.id === movementId) ?? STUDY_MOVEMENTS[0];
  const currentStep = STUDY_TOUR.findIndex(t => t.key === scene);
  const step = STUDY_TOUR[Math.max(0, currentStep)];
  const selectedSession = STUDY_HISTORY.find(x => x.id === sessionId) ?? STUDY_HISTORY[0];
  const history = STUDY_HISTORY.filter(h => (historyFilter !== 'prs' || h.record) && `${h.name} ${h.detail} ${h.record || ''} ${h.date}`.toLowerCase().includes(query.toLowerCase()));
  const movements = STUDY_MOVEMENTS.filter(m => m.family === family);
  const matches = firstWeek ? [] : searchQuery.trim() ? STUDY_MOVEMENTS.filter(m => `${m.name} ${m.equipment} ${m.family}`.toLowerCase().includes(searchQuery.trim().toLowerCase())) : STUDY_MOVEMENTS.filter(m => m.family === 'core');
  const coreDetail = STUDY_CORE_DETAILS[selectedMovement.id] ?? STUDY_CORE_DETAILS['example-squat'];
  const series = useMemo(() => coreDetail.dates.map((date, index) => ({ date, value: Number(studyWeight(coreDetail[metric][index], unit).replace(/,/g, '')), meta: { reps: metric === 'five' ? 5 : 1 } })).filter(p => range !== '6w' || p.date >= '2026-09-18'), [coreDetail, metric, range, unit]);
  const clubState = resolvePlateClubState(195, 'squat', unit)!;
  const club = unit === 'kg' ? { threshold: 150, next: 200, render: 330, date: 'Aug 10', kg: 170, fullDate: 'August 10, 2026' } : { threshold: 405, next: 455, render: 405, date: 'Oct 2', kg: 185, fullDate: 'October 2, 2026' };
  const currentLoad = Number(studyWeight(195, unit).replace(/,/g, ''));
  const clubRemaining = clubState.remaining!;
  useEffect(() => { savedScenes.current[tab] = scene; }, [scene, tab]);
  const jump = (next: StudyScene) => { setQuery(''); setSheet(null); setFirstWeek(next === 'empty'); savedScenes.current = { records: next === 'empty' ? 'empty' : 'record', history: 'history', milestones: 'milestones' }; setScene(next); setTab(['history', 'session'].includes(next) ? 'history' : ['milestone', 'milestones'].includes(next) ? 'milestones' : 'records'); if (next === 'movement') { setFamily('accessories'); setMovementId('example-assisted-pullup'); } if (next === 'record' || next === 'empty' || next === 'lift') setFamily('core'); if (next === 'lift') setMovementId('example-squat'); };
  const selectTab = (next: StudyTab, root = false) => { setTab(next); setScene(root ? next === 'records' ? firstWeek ? 'empty' : 'record' : next : savedScenes.current[next]); };
  const openMovement = (m: StudyMovement) => { setMovementId(m.id); setFamily(m.family); setTab('records'); setScene(m.family === 'core' ? 'lift' : 'movement'); setSheet(null); };
  const back = () => { if (sheet) { setSheet(null); return; } if (scene === 'session') setScene('history'); else if (scene === 'milestone') setScene('milestones'); else { setScene(firstWeek ? 'empty' : 'record'); setTab('records'); } };
  const showSet = (overrides: Partial<typeof evidence> = {}) => { setEvidence({ assisted: false, equipment: 'Barbell', name: 'Competition Squat', kg: 170, reps: 5, rpe: 8, date: 'October 28, 2026', session: 'Lower · Week 4', note: '5-rep best', previousKg: 165, ...overrides }); setSheet('set'); };
  useEffect(() => { const frame = requestAnimationFrame(() => scroll.current?.scrollTo({ y: offsets.current[location] ?? 0, animated: false })); return () => cancelAnimationFrame(frame); }, [location]);
  useEffect(() => { const sub = BackHandler.addEventListener('hardwareBackPress', () => { if (sheet || !['record', 'empty', 'history', 'milestones'].includes(scene)) { back(); return true; } return false; }); return () => sub.remove(); });
  useEffect(() => { if (Platform.OS !== 'web') return; const handler = (e: KeyboardEvent) => { if (e.key === 'Escape' && sheet) setSheet(null); }; globalThis.addEventListener?.('keydown', handler); return () => globalThis.removeEventListener?.('keydown', handler); }, [sheet]);

  const top = <>
    <View style={s.phoneHeader}><View style={s.brandMark}><View style={s.brandRule} /><Eyebrow color={C.secondary}>STRENGTH LEDGER</Eyebrow></View><View style={s.headerActions}><Pressable testID="study-unit-toggle" accessibilityRole="button" accessibilityLabel={`Weight unit ${unit}. Switch units`} onPress={() => setUnit(u => u === 'kg' ? 'lb' : 'kg')} style={s.unitButton}><Text style={s.unitText}>{unit}</Text><Icon name="swap-horizontal" size={14} color={C.muted} /></Pressable><IconButton name="search-outline" label="Search the Ledger" onPress={() => { setSearchQuery(''); setSheet('search'); }} /></View></View>
    {['record', 'empty', 'history', 'milestones'].includes(scene) ? <View style={s.titleRow}><View style={s.flex}><Eyebrow>{firstWeek ? 'YOUR FIRST CHAPTER' : 'ALEX MORGAN · YOUR TRAINING RECORD'}</Eyebrow><Text style={s.pageTitle}>The Ledger</Text></View><Pressable onPress={() => setSheet('guide')} accessibilityRole="button" accessibilityLabel="Open design study guide" style={s.exampleBadge}><View style={s.exampleDot} /><Text style={s.exampleText}>Example data</Text></Pressable></View> : null}
    <View accessibilityRole="tablist" style={s.tabs}>{(['records', 'history', 'milestones'] as const).map(t => <Pressable testID={`study-tab-${t}`} key={t} accessibilityRole="tab" accessibilityState={{ selected: tab === t }} aria-selected={tab === t} onPress={() => selectTab(t)} style={[s.tab, tab === t && s.selectedTab]}><Text style={[s.tabText, tab === t && s.selectedTabText]}>{TAB_LABELS[t]}</Text>{tab === t ? <View style={s.selectedLine} /> : null}</Pressable>)}</View>
  </>;

  const recentBest = <Pressable testID="study-highlight" accessibilityRole="button" accessibilityLabel="Inspect the squat 5-rep personal record" onPress={() => showSet()} style={({ pressed }) => [s.highlight, pressed && s.pressed]}><View style={s.spread}><Eyebrow color={C.success}>LATEST PERSONAL BEST</Eyebrow><Text style={s.caption}>Oct 28</Text></View><Text style={s.highlightTitle}>Squat · 5-rep record</Text><Load kg={170} reps={5} unit={unit} large compact /><View style={s.highlightFoot}><View style={s.deltaMark}><Icon name="arrow-up-right-box-outline" color={C.success} size={17} /><Text style={s.positive}>+{studyWeight(5, unit)} {unit}</Text></View><Text style={s.caption}>Squat · previous {studyWeight(165, unit)} × 5</Text><Icon name="arrow-forward" color={C.text} size={18} /></View></Pressable>;
  const records = <>
    {firstWeek ? <Empty icon="book-outline" title="Your record starts here." body="Your first logged sets create your history. Personal bests and trends appear as that history grows." /> : null}
    <Section title="Your strength record" detail={family === 'core' ? 'Best logged singles · source evidence one tap away' : 'Exact movements. Independent histories.'} />
    <FamilyPicker value={family} onChange={setFamily} />
    {firstWeek && family !== 'core' ? <Empty icon="barbell-outline" title={family === 'variants' ? 'Your variations will live here.' : 'Your accessory record will grow here.'} body="Log this work in a Session and its exact movement history appears here." /> : firstWeek ? <View style={s.firstRows}>{STUDY_MOVEMENTS.filter(m => m.family === 'core').map(m => <View key={m.id} style={s.movementRow}><View style={[s.liftMark, { backgroundColor: tone(m) }]} /><View style={s.flex}><Text style={s.rowTitle}>{m.shortName}</Text><Text style={s.caption}>No performed sets yet</Text></View><Text style={s.emptyDash}>—</Text></View>)}</View> : family === 'variants' ? <><Text style={s.explanatory}>Each variation has its own record. Grouped by its parent lift.</Text>{(['squat', 'bench', 'deadlift'] as const).map(parent => <View key={parent}><View style={s.groupTitle}><View style={[s.familyDot, { backgroundColor: C[parent] }]} /><Eyebrow>{parent === 'bench' ? 'BENCH PRESS' : parent.toUpperCase()} FAMILY</Eyebrow></View>{movements.filter(m => m.parent === parent).map(m => <MovementRow key={m.id} m={m} unit={unit} onPress={() => openMovement(m)} />)}</View>)}</> : <>{family === 'accessories' ? <Text style={s.explanatory}>Exact movement. Exact equipment. An honest comparison.</Text> : null}{movements.map(m => <MovementRow key={m.id} m={m} unit={unit} onPress={() => openMovement(m)} />)}</>}
    {!firstWeek && family === 'core' ? <View style={s.recentBestWrap}>{recentBest}</View> : null}
    <View style={s.sectionGap} /><LinkRow title="Training context" detail="Bodyweight, volume and muscle balance" name="body-outline" onPress={() => setScene('context')} />
    <LinkRow title="All recorded performances" detail="Find the Session or set behind a number" name="time-outline" onPress={() => selectTab('history', true)} />
    {firstWeek ? <View style={s.firstNote}><Icon name="shield-checkmark-outline" color={C.teal} /><Text style={s.bodyCopy}>Nothing to unlock. All three sections are ready when your evidence is.</Text></View> : <View style={s.recordFooter}><Text style={s.caption}>146 Sessions</Text><View style={s.separatorDot} /><Text style={s.caption}>Since March 2025</Text><View style={s.separatorDot} /><Text style={s.caption}>Your record stays yours</Text></View>}
  </>;

  const lift = <>
    <Back label="Records" onPress={back} /><Eyebrow color={tone(selectedMovement)}>COMPETITION LIFT</Eyebrow><Text style={s.detailTitle}>{selectedMovement.shortName}</Text>
    <View style={s.detailHero}><Eyebrow>HEAVIEST LOGGED SINGLE · {selectedMovement.date.toUpperCase()}</Eyebrow><Load kg={selectedMovement.kg} unit={unit} large /><Text style={s.bodyCopy}>1 rep · recorded performance</Text></View>
    <View style={s.spread}><Text style={s.sectionTitle}>Progress over time</Text><Pressable accessibilityRole="button" onPress={() => setSheet('method')} style={s.iconButton} accessibilityLabel="How to read these records"><Icon name="information-circle-outline" /></Pressable></View>
    <View style={s.metricPicker}>{(['top', 'five'] as const).map(k => <Pressable accessibilityRole="tab" accessibilityState={{ selected: metric === k }} aria-selected={metric === k} testID={`study-metric-${k}`} key={k} onPress={() => setMetric(k)} style={[s.metricChip, metric === k && s.metricChipSelected]}><Text style={[s.small, metric === k && s.selectedTabText]}>{k === 'top' ? 'Session top load' : '5-rep record'}</Text></Pressable>)}</View>
    <View accessibilityRole="tablist" style={s.rangeRow}>{(['6w', '12w', 'all'] as const).map(r => <Pressable key={r} testID={`study-range-${r}`} accessibilityRole="tab" accessibilityState={{ selected: range === r }} aria-selected={range === r} onPress={() => setRange(r)} style={[s.rangeChip, r === range && s.rangeChipSelected]}><Text style={r === range ? s.rangeActiveText : s.rangeText}>{r === 'all' ? 'All time' : r === '6w' ? '6 weeks' : '12 weeks'}</Text></Pressable>)}</View>
    <View style={s.chartWrap} testID="study-analytical-chart"><AnalyticalTimeSeriesChart series={[{ key: metric, label: metric === 'top' ? 'Session top load' : '5-rep record', color: tone(selectedMovement), points: series }]} metric={analyticalMetricDefinition('ledger-study-load', { label: 'Recorded load', kind: 'weight', unit, axisUnit: unit, includeZero: false, maximumFractionDigits: 1 })} showLegend={false} selectedInitially="latest" height={225} readableText tooltipRows={p => [`${metric === 'five' ? '5 repetitions' : 'Session top set'} · ${p.date.slice(0, 10)}`]} testID="ledger-study-shared-chart" /></View>
    <Section title="Rep records" detail="Best performed load at each exact rep count." />
    <View style={s.tableHead}><Text style={[s.caption, s.repCell]}>REPS</Text><Text style={[s.caption, s.flex]}>BEST LOAD</Text><Text style={s.caption}>RECORDED</Text></View>{coreDetail.repBests.map(({ reps, kg, date, rpe }) => <Pressable testID={`study-rep-${reps}`} accessibilityRole="button" accessibilityLabel={`Inspect ${reps}-rep record`} key={reps} style={s.tableRow} onPress={() => showSet({ name: selectedMovement.name, kg, reps, rpe, date: new Date(date + 'T12:00:00Z').toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' }), previousKg: reps === 5 && selectedMovement.parent === 'squat' ? 165 : null, note: `${reps}-rep best` })}><Text style={[s.tableValue, s.repCell]}>{reps}</Text><Text style={[s.tableValue, s.flex]}>{studyWeight(kg, unit)} <Text style={s.caption}>{unit}</Text></Text><Text style={s.caption}>{new Date(date + 'T12:00:00Z').toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' })}</Text><Icon name="chevron-forward" size={15} color={C.muted} /></Pressable>)}
    <View style={s.estimatePanel}><View style={s.spread}><Eyebrow>ESTIMATED 1RM</Eyebrow><Text style={s.caption}>Calculation</Text></View><Load kg={estimateMovementStrengthKg(strengthMetricForMovementClass('core'), coreDetail.repBests[2].kg, 5, coreDetail.repBests[2].rpe)!} unit={unit} /><Text style={s.caption}>From {studyWeight(coreDetail.repBests[2].kg, unit)} {unit} × 5 @ RPE {coreDetail.repBests[2].rpe}. A training estimate, not a logged single.</Text></View>
    <View style={s.sectionGap} /><LinkRow title="Strength standards & estimates" detail="Reference cohort, estimated 1RM and methodology" name="analytics-outline" onPress={() => setSheet('method')} /><LinkRow title={`${selectedMovement.shortName} variations`} detail={`Separate records in the ${selectedMovement.shortName} family`} name="git-branch-outline" onPress={() => { setFamily('variants'); setScene('record'); }} />
  </>;

  const movement = <>
    <Back label={selectedMovement.family === 'variants' ? 'Variants' : 'Accessories'} onPress={back} /><Eyebrow color={tone(selectedMovement)}>{selectedMovement.family === 'variants' ? `${selectedMovement.parent?.toUpperCase()} FAMILY · INDEPENDENT RECORD` : 'EXACT MOVEMENT RECORD'}</Eyebrow><Text style={s.detailTitle}>{selectedMovement.name}</Text>
    {selectedMovement.assisted ? <><Text style={s.fieldLabel}>Equipment context</Text><View style={s.brandPicker}>{STUDY_MOVEMENTS.filter(m => m.assisted).map(m => <Pressable accessibilityRole="tab" accessibilityState={{ selected: movementId === m.id }} aria-selected={movementId === m.id} testID={`study-brand-${m.equipment.replace(/ /g, '-').toLowerCase()}`} key={m.id} onPress={() => setMovementId(m.id)} style={[s.brandChip, movementId === m.id && s.metricChipSelected]}><Text style={s.small}>{m.equipment}</Text></Pressable>)}</View></> : <Text style={s.bodyCopy}>{selectedMovement.equipment}</Text>}
    <View style={s.detailHero}><Eyebrow>{selectedMovement.baseline ? 'FIRST LOGGED BASELINE' : selectedMovement.assisted ? 'LOWEST ASSISTANCE AT 8 REPS' : `BEST ${selectedMovement.reps}-REP SET`}</Eyebrow><Load kg={selectedMovement.kg} unit={unit} large /><Text style={s.bodyCopy}>{selectedMovement.assisted ? 'assistance' : 'performed load'} × {selectedMovement.reps} reps · {selectedMovement.date}</Text>{studyImprovement(selectedMovement) != null ? <Text style={s.positive}>{selectedMovement.assisted ? '↓ ' : '+ '}{studyWeight(studyImprovement(selectedMovement)!, unit)} {unit} {selectedMovement.assisted ? 'less assistance' : 'more at the same reps'}</Text> : <Text style={s.caption}>A starting point for this machine. No PR claimed.</Text>}</View>
    <View style={s.contextNote}><Icon name="shield-checkmark-outline" color={C.teal} /><Text style={s.bodyCopy}>{selectedMovement.assisted ? 'Less assistance means you performed more of the lift yourself. Only this manufacturer’s comparable sets belong in this record.' : 'This variation owns its own performed-set history. Its progress is separate from your Competition lift.'}</Text></View>
    <Section title="Comparable performances" detail={selectedMovement.equipment} />{[selectedMovement.kg, selectedMovement.previousKg].filter((v): v is number => v != null).map((kg, i) => <Pressable key={i} accessibilityRole="button" accessibilityLabel={`Open ${i ? 'previous' : 'latest'} performed set`} style={s.comparisonRow} onPress={() => showSet({ name: selectedMovement.name, kg, reps: selectedMovement.reps, assisted: !!selectedMovement.assisted, equipment: selectedMovement.equipment, date: i ? 'October 13, 2026' : 'October 27, 2026', previousKg: i ? null : selectedMovement.previousKg, note: selectedMovement.assisted ? 'Assistance recorded' : 'Exact variant set' })}><View style={s.flex}><Text style={s.rowTitle}>{i ? 'Previous best' : selectedMovement.baseline ? 'First exposure' : 'Latest best'}</Text><Text style={s.caption}>{i ? 'Oct 13' : selectedMovement.date} · {selectedMovement.equipment}</Text></View><Load kg={kg} unit={unit} reps={selectedMovement.reps} /><Icon name="chevron-forward" size={16} /></Pressable>)}
    <Section title="Training exposure" /><View style={s.exposureRow}><View style={s.flex}><Text style={s.mediumNumber}>{selectedMovement.sessions}</Text><Text style={s.caption}>Sessions recorded</Text></View><View style={s.flex}><Text style={s.mediumNumber}>{selectedMovement.baseline ? '1' : '3'}</Text><Text style={s.caption}>Training blocks</Text></View></View>
  </>;

  const historyContent = <><View style={s.sectionHeading}><View><Text style={s.detailTitle}>Your work, on record.</Text><Text style={s.bodyCopy}>Sessions, personal bests and their context.</Text></View></View><View style={s.searchField}><Icon name="search-outline" size={19} color={C.muted} /><TextInput testID="study-history-search" accessibilityLabel="Search history" placeholder="Find a lift, Session or date" placeholderTextColor={C.muted} value={query} onChangeText={setQuery} style={s.input} /></View><View style={s.metricPicker}>{(['all', 'prs'] as const).map(f => <Pressable testID={`study-history-${f}`} key={f} accessibilityRole="tab" accessibilityState={{ selected: f === historyFilter }} aria-selected={f === historyFilter} onPress={() => setHistoryFilter(f)} style={[s.metricChip, f === historyFilter && s.metricChipSelected]}><Text style={s.small}>{f === 'all' ? 'All entries' : 'Personal bests'}</Text></Pressable>)}</View>{firstWeek ? <Empty icon="time-outline" title="Your first Session goes here." body="Completed work creates a dated, searchable record. You can always trace a personal best back to its set." /> : <><View style={s.timelineMonth}><Eyebrow color={C.secondary}>BUILD · AUTUMN 2026</Eyebrow><Text style={s.caption}>{history.length} matching Sessions</Text></View>{history.length ? history.map(h => <Pressable testID={`study-history-entry-${h.id}`} key={h.id} accessibilityRole="button" accessibilityLabel={`Open ${h.name}, ${h.date}`} onPress={() => { setSessionId(h.id); setScene('session'); }} style={({ pressed }) => [s.historyRow, pressed && s.pressed]}><View style={s.dateColumn}><Text style={s.dateNumber}>{h.date.split(' ')[1]}</Text><Text style={s.dateMonth}>{h.date.split(' ')[0].toUpperCase()}</Text><View style={s.timelineLine} /></View><View style={s.historyCopy}><View style={s.spread}><Text style={s.rowTitle}>{h.name}</Text><Icon name="chevron-forward" size={16} color={C.muted} /></View><Text style={s.caption}>{h.detail}</Text><Text style={s.caption}>{h.sets} sets · {h.time}</Text>{h.record ? <View style={s.historySignal}><Icon name="trending-up" color={C.success} size={15} /><Text style={s.historySignalText}>{h.record.replace('170 kg', `${studyWeight(170, unit)} ${unit}`).replace('195 kg', `${studyWeight(195, unit)} ${unit}`).replace('180 kg', `${studyWeight(180, unit)} ${unit}`)}</Text></View> : null}</View></Pressable>) : <Empty icon="search-outline" title="No matching history." body="Try a movement name, a Session name or another date." />}</>}</>;

  const session = <SessionPreview key={sessionId} entry={selectedSession} unit={unit} onBack={back} onSet={data => showSet(data)} />;

  const milestones = <><View style={s.sectionHeading}><View><Text style={s.detailTitle}>Earned through the work.</Text><Text style={s.bodyCopy}>Your clubs, tiers and accumulated training.</Text></View></View>{firstWeek ? <Empty icon="ribbon-outline" title="Your first milestone is ahead." body="Recognition appears when your logged work qualifies. Your record is already worth keeping." /> : <><Pressable testID="study-earned-club" accessibilityRole="button" accessibilityLabel="Open earned Squat club" style={({ pressed }) => [s.earnedClub, pressed && s.pressed]} onPress={() => setScene('milestone')}><View style={s.spread}><Eyebrow color={C.gold}>EARNED CLUB</Eyebrow><Icon name="checkmark-circle" color={C.gold} size={18} /></View><Text style={s.clubNumber}>{club.threshold}<Text style={s.clubUnit}> {unit}</Text></Text><Text style={s.clubTitle}>Squat club</Text><View style={s.spread}><Text style={s.caption}>Earned {club.date}, 2026</Text><Icon name="arrow-forward" color={C.text} size={20} /></View></Pressable><Section title="The next landmark" /><View style={s.nextLandmark}><View style={s.spread}><Text style={s.rowTitle}>{club.next} {unit} Squat club</Text><Text style={s.caption}>{clubRemaining} {unit} to go</Text></View><View style={s.progressTrack}><View style={[s.progressFill, { width: `${clubState.progress * 100}%` }]} /></View><Text style={s.caption}>Best logged single: {studyWeight(195, unit)} {unit}. Earned by a performed set.</Text></View></>}
    <Section title="Your collections" /><LinkRow name="barbell-outline" title="Plate clubs" detail="Individual lift milestones, with qualifying sets" onPress={() => firstWeek ? setSheet('method') : setScene('milestone')} /><LinkRow name="podium-outline" title="Strength tiers" detail="Standards, reference context and qualification" onPress={() => setSheet('tiers')} /><LinkRow name="ribbon-outline" title="Volume awards" detail="Accumulated work across your training" onPress={() => setSheet('volume')} /><LinkRow name="trending-up-outline" title="Personal-best history" detail="All your record-setting performances" onPress={() => { selectTab('history', true); setHistoryFilter('prs'); }} />
  </>;
  const milestone = <><Back label="Milestones" onPress={back} /><Eyebrow color={C.gold}>EARNED · {club.date.toUpperCase()}, 2026</Eyebrow><Text style={s.detailTitle}>{club.threshold} {unit} Squat club</Text><View style={s.artifactStage}><View style={s.awardRule} /><Icon name="ribbon-outline" color={C.gold} size={30} /><Text style={s.awardNumber}>{club.threshold}<Text style={s.awardUnit}> {unit}</Text></Text><Text style={s.awardLabel}>SQUAT CLUB</Text><View style={s.awardRule} /><Eyebrow color={C.gold}>EARNED THROUGH A RECORDED LIFT</Eyebrow></View><Section title="The set that earned it" /><View style={s.qualifiedCard}><Text style={s.rowTitle}>Competition Squat</Text><Load kg={club.kg} unit={unit} reps={1} large /><Text style={s.bodyCopy}>{club.fullDate} · Barbell</Text><Text style={s.caption}>A recorded single above the {club.threshold} {unit} threshold.</Text><Button label="View qualifying set" testID="study-club-proof" onPress={() => showSet({ kg: club.kg, reps: 1, rpe: 8, date: club.fullDate, session: 'Lower · Foundation', note: `${club.threshold} ${unit} Squat club`, previousKg: null })} icon="arrow-forward" /></View><Text style={s.explanatory}>A lasting milestone, with a real performance behind it.</Text></>;
  const context = firstWeek ? <><Back label="Records" onPress={back} /><Empty icon="body-outline" title="Context follows your training." body="Reported bodyweight and completed training will appear here. No bodyweight, volume or muscle exposure has been invented for this first-week example." /></> : <><Back label="Records" onPress={back} /><Eyebrow>SUPPORTING YOUR STRENGTH RECORD</Eyebrow><Text style={s.detailTitle}>Training context</Text><Section title="Bodyweight" detail="Latest reported · Oct 29" /><View style={s.bodyweight}><Load kg={83.2} unit={unit} large /><Text style={s.caption}>Reported, not inferred from your lifts</Text></View><Section title="Weekly training" detail="Oct 19–25 · completed work" /><View style={s.exposureRow}><View style={s.flex}><Text style={s.mediumNumber}>4</Text><Text style={s.caption}>Sessions</Text></View><View style={s.flex}><Text style={s.mediumNumber}>58</Text><Text style={s.caption}>Performed sets</Text></View></View><Section title="Muscle-group exposure" detail="Performed sets · primary involvement" />{[{ name: 'Quads', sets: 14 }, { name: 'Back', sets: 12 }, { name: 'Chest', sets: 10 }, { name: 'Hamstrings', sets: 8 }].map(r => <View key={r.name} style={s.muscleRow}><Text style={[s.rowTitle, s.muscleName]}>{r.name}</Text><View style={s.muscleTrack}><View style={[s.muscleFill, { width: `${r.sets / 14 * 100}%` }]} /></View><Text style={s.tableValue}>{r.sets}</Text></View>)}<Text style={s.explanatory}>Exposure describes your logged work. It is not a claim about muscle growth or the cause of a strength gain.</Text><LinkRow name="time-outline" title="View this week’s Sessions" detail="Follow the context back to the work" onPress={() => selectTab('history', true)} /></>;

  const content = scene === 'lift' ? lift : scene === 'movement' ? movement : scene === 'session' ? session : scene === 'milestone' ? milestone : scene === 'context' ? context : tab === 'history' ? historyContent : tab === 'milestones' ? milestones : records;
  const phone = <View style={[s.phone, desktop && s.phoneStudio, desktop && { height: Math.min(850, dimensions.height - 200) }, !embedded && !desktop && dimensions.width >= 600 && { width: 430, alignSelf: 'center', borderLeftWidth: 1, borderRightWidth: 1, borderColor: C.line }]} testID="ledger-design-study"><View style={s.phoneTop}>{top}</View><ScrollView ref={scroll} testID="study-content" showsVerticalScrollIndicator={false} onScroll={e => { offsets.current[location] = e.nativeEvent.contentOffset.y; }} scrollEventThrottle={16} contentContainerStyle={s.content}>{content}<View style={s.contentEnd} /></ScrollView><View style={s.dock} accessibilityLabel="App navigation context. Ledger selected. Other app sections are outside this storyboard.">{([{ icon: 'home-outline', name: 'Today' }, { icon: 'barbell-outline', name: 'Training' }, { icon: 'calendar-outline', name: 'Calendar' }, { icon: 'book-outline', name: 'Ledger' }, { icon: 'person-outline', name: 'You' }] as { icon: IconName; name: string }[]).map(n => <View key={n.name} style={s.dockItem}><Icon name={n.icon} size={21} color={n.name === 'Ledger' ? C.accent : C.muted} /><Text style={[s.dockLabel, n.name === 'Ledger' && { color: C.accent }]}>{n.name}</Text>{n.name === 'Ledger' ? <View style={s.dockSelected} /> : null}</View>)}</View></View>;
  return <View style={s.root}>
    {desktop ? <><View style={s.studioHeader}><View><Eyebrow color={C.accent}>STRENGTH LEDGER / DESIGN STUDY 01</Eyebrow><Text style={s.studioTitle}>The record, clarified.</Text></View><View style={s.studioHeaderRight}><Text style={s.caption}>Graphite · editorial hierarchy · evidence first</Text><Button quiet label={firstWeek ? 'Show mature record' : 'Try first-week state'} onPress={() => jump(firstWeek ? 'record' : 'empty')} /></View></View><View style={s.studioBody}><ScrollView style={s.tourRail} showsVerticalScrollIndicator={false}><Eyebrow>FOLLOW THE STORY</Eyebrow>{STUDY_TOUR.map((t, i) => <Pressable testID={`study-tour-${t.key}`} accessibilityRole="button" accessibilityLabel={`${i + 1}. ${t.title}`} key={t.key} onPress={() => jump(t.key)} style={[s.tourStep, scene === t.key && s.tourSelected]}><Text style={[s.stepNumber, scene === t.key && { color: C.accent }]}>{String(i + 1).padStart(2, '0')}</Text><View style={s.flex}><Text style={s.tourTitle}>{t.title}</Text><Text style={s.tourPath}>{t.path}</Text></View></Pressable>)}<View style={s.tourFooter}><Eyebrow>THE NAVIGATION RULE</Eyebrow><Text style={s.railCopy}>Three destinations. One detail level. Source evidence opens in place.</Text><Text style={s.caption}>Fictional example data. Production and your actual records are unchanged.</Text></View></ScrollView><View style={s.stage}>{phone}<Text style={s.stageCaption}>Interactive React Native study · select, inspect, go back</Text></View><ScrollView style={s.notes} showsVerticalScrollIndicator={false}><Eyebrow color={C.accent}>WHY THIS SCREEN</Eyebrow><Text style={s.noteTitle}>{step.title}</Text><Text style={s.noteTask}>{step.task}</Text><Text style={s.noteCopy}>{step.why}</Text><View style={s.noteRule} /><Eyebrow>DESIGN DIRECTION</Eyebrow><Text style={s.noteTitleSmall}>Precision, without the clutter.</Text><Text style={s.noteCopy}>Readable Exo 2. Clear charcoal surfaces. Chalk actions. Lift color stays meaningful. Records lead; decoration steps back.</Text><View style={s.swatches}>{[C.canvas, C.panel, C.text, C.accent, C.success].map(color => <View key={color} style={[s.swatch, { backgroundColor: color }]} />)}</View><View style={s.noteRule} /><Eyebrow>RESEARCH, APPLIED</Eyebrow>{REFERENCES.map(r => <Pressable key={r.title} accessibilityRole="link" onPress={() => void Linking.openURL(r.url)} style={s.reference}><View style={s.spread}><Text style={s.referenceTitle}>{r.title}</Text><Icon name="arrow-up-right-box-outline" size={15} color={C.muted} /></View><Text style={s.caption}>{r.note}</Text></Pressable>)}<View style={s.noteRule} /><Button label="Next in the story" icon="arrow-forward" onPress={() => jump(STUDY_TOUR[(currentStep + 1) % STUDY_TOUR.length].key)} /></ScrollView></View></> : <>{!embedded ? <View style={s.mobileLabBar}><Text style={s.caption}>DEV design study · {Math.max(0, currentStep) + 1} / {STUDY_TOUR.length}</Text><Pressable onPress={() => jump(STUDY_TOUR[(currentStep + 1) % STUDY_TOUR.length].key)} accessibilityRole="button" accessibilityLabel="Next storyboard screen" style={s.mobileNext}><Text style={s.actionText}>Next</Text><Icon name="arrow-forward" size={17} /></Pressable></View> : null}{phone}</>}
    <Modal visible={sheet != null} transparent animationType="fade" onRequestClose={() => setSheet(null)}><View style={s.modalScrim}><Pressable style={StyleSheet.absoluteFill} accessibilityRole="button" accessibilityLabel="Dismiss detail" onPress={() => setSheet(null)} /><View testID="study-sheet" style={[s.sheet, desktop && s.sheetDesktop]} accessibilityViewIsModal><View style={s.sheetHeader}><View style={s.flex}><Eyebrow color={sheet === 'set' ? C.success : C.accent}>{sheet === 'set' ? 'SOURCE EVIDENCE' : 'THE LEDGER'}</Eyebrow><Text style={s.sheetTitle}>{sheet === 'set' ? 'Recorded set' : sheet === 'search' ? 'Find your record' : sheet === 'guide' ? 'The design study' : sheet === 'tiers' ? 'Strength tiers' : sheet === 'volume' ? 'Volume awards' : 'Reading your record'}</Text></View><IconButton name="close" label="Close detail" onPress={() => setSheet(null)} /></View><ScrollView contentContainerStyle={s.sheetContent} keyboardShouldPersistTaps="handled">{sheet === 'set' ? <><Text style={s.sectionTitle}>{evidence.name}</Text><Load kg={evidence.kg} reps={evidence.reps} unit={unit} assistance={evidence.assisted} large /><View style={s.evidenceMeta}><Text style={s.bodyCopy}>RPE {evidence.rpe}</Text><Text style={s.bodyCopy}>{evidence.date}</Text></View><Text style={s.caption}>{evidence.equipment}{evidence.assisted ? ' · assistance recorded' : ' · performed load'}</Text><View style={s.evidenceRule} /><Eyebrow>{evidence.note.toUpperCase()}</Eyebrow>{evidence.previousKg != null ? <Text style={s.bodyCopy}>Previous comparable set: {studyWeight(evidence.previousKg, unit)} {unit} × {evidence.reps}. Same movement, rep count and equipment context.</Text> : <Text style={s.bodyCopy}>This is a performed set. It is not an estimated max.</Text>}<View style={s.sourceContext}><Icon name="document-text-outline" color={C.teal} /><View style={s.flex}><Text style={s.rowTitle}>{evidence.session}</Text><Text style={s.caption}>Autumn Build · original logged set</Text></View></View><Button label="Return to the record" onPress={() => setSheet(null)} icon="arrow-back" /></> : sheet === 'search' ? <><View style={s.searchField}><Icon name="search-outline" /><TextInput autoFocus testID="study-global-search" accessibilityLabel="Search all movements" value={searchQuery} onChangeText={setSearchQuery} placeholder="Squat, pull-up, equipment…" placeholderTextColor={C.muted} style={s.input} /></View><Text style={s.caption}>{searchQuery ? `${matches.length} matching movement records` : 'Start with a lift, or search your movements.'}</Text>{matches.map(m => <MovementRow key={m.id} m={m} unit={unit} onPress={() => openMovement(m)} />)}{!matches.length ? <Empty icon="search-outline" title="No matching record." body="Try a movement name or equipment manufacturer." /> : null}</> : sheet === 'tiers' ? <TierCollection unit={unit} firstWeek={firstWeek} /> : sheet === 'volume' ? <VolumeCollection unit={unit} firstWeek={firstWeek} onHistory={() => { setSheet(null); selectTab('history', true); }} /> : sheet === 'guide' ? <><Text style={s.bodyCopy}>A research-backed proposal for a clearer Ledger. All numbers here are fictional examples. Your actual Ledger and records stay unchanged.</Text>{STUDY_TOUR.map((t, i) => <LinkRow key={t.key} title={`${i + 1}. ${t.title}`} detail={t.task} name="arrow-forward-outline" onPress={() => jump(t.key)} />)}{onExit ? <Button quiet label="Exit design study" onPress={onExit} /> : null}</> : <><Text style={s.emptyTitle}>Performed facts first.</Text><Text style={s.bodyCopy}>Top load is what you lifted. A rep record is the highest performed load at that rep count. Estimated 1RM is a calculation with a source set, not a recorded single.</Text><Text style={s.bodyCopy}>The chart uses dated observations, labelled units and a numeric scale. Tap or drag to inspect a point. Variants and machine equipment contexts keep separate histories.</Text><Button quiet label="Return to the record" onPress={() => setSheet(null)} icon="arrow-back" /></>}</ScrollView></View></View></Modal>
  </View>;
}
function TierCollection({ unit, firstWeek }: { unit: StudyUnit; firstWeek: boolean }) {
  const [lift, setLift] = useState<'total' | 'squat' | 'bench' | 'deadlift'>('squat');
  if (firstWeek) return <Empty icon="podium-outline" title="Your reference starts with evidence." body="Logged competition lifts create your strength profile. Tier qualification keeps its reference context; a first-week record has no invented standing." />;
  const standard = strengthTierCertificationFixture('M', 'mid').strengthStandard!;
  const kg = lift === 'total' ? 540 : STUDY_MOVEMENTS.find(m => m.family === 'core' && m.parent === lift)!.kg;
  const state = strengthTierState(kg, lift, standard, unit)!;
  const name = lift === 'total' ? totalStrengthClubName(state.earnedTierIndex) + ' Club' : state.tiers[state.earnedTierIndex]?.name || 'Below first tier';
  return <><View style={s.metricPicker}>{(['squat','bench','deadlift','total'] as const).map(key => <Pressable key={key} testID={`study-tier-${key}`} accessibilityRole="tab" accessibilityState={{ selected: lift === key }} aria-selected={lift === key} onPress={() => setLift(key)} style={[s.metricChip, lift === key && s.metricChipSelected]}><Text style={s.small}>{key === 'total' ? 'Total' : key === 'bench' ? 'Bench' : key[0].toUpperCase() + key.slice(1)}</Text></Pressable>)}</View><Eyebrow color={C.accent}>CURRENT REFERENCE POSITION</Eyebrow><Text style={s.detailTitle}>{name}</Text><Load kg={kg} unit={unit} /><Text style={s.bodyCopy}>{lift === 'total' ? 'Sum of best logged singles from separate Sessions. This is not a meet total.' : 'Best logged single · performed load'}</Text><View style={s.contextNote}><Icon name="information-circle-outline" color={C.teal} /><Text style={s.bodyCopy}>Example reference cohort: male, raw full-power lifters. Tier labels and thresholds use the existing governed reference. This is comparison context, not a forecast.</Text></View>{state.tiers.map((tier, i) => <View key={tier.tier} style={s.tableRow}><Icon name={i <= state.earnedTierIndex ? 'checkmark-circle-outline' : 'ellipse-outline'} color={i <= state.earnedTierIndex ? C.accent : C.muted} size={19} /><Text style={[s.rowTitle, s.flex]}>{lift === 'total' ? totalStrengthClubName(i) : tier.name}</Text><Text style={s.tableValue}>{studyWeight(tier.threshold_kg, unit)} {unit}</Text></View>)}</>;
}
function VolumeCollection({ unit, firstWeek, onHistory }: { unit: StudyUnit; firstWeek: boolean; onHistory: () => void }) {
  const [family, setFamily] = useState<VolumeAchievementContextId>('total');
  const volumeKg = { total: 486000, squat: 180000, bench: 110000, deadlift: 195000 }[family];
  const volumeLb = volumeKg * 2.2046226218487757;
  const progress = deriveVolumeAchievement(volumeLb, family, unit);
  const reference = progress.achieved ? deriveVolumeComparisonPresentation(progress.achieved, family, volumeLb) : null;
  if (firstWeek) return <Empty icon="ribbon-outline" title="Your work will add up here." body="Performed load × reps contributes to your volume record. Earned medallions and muscle-group awards will appear with their qualifying history." />;
  return <><View style={s.metricPicker}>{(['total','squat','bench','deadlift'] as const).map(key => <Pressable key={key} testID={`study-volume-${key}`} accessibilityRole="tab" accessibilityState={{ selected: family === key }} aria-selected={family === key} onPress={() => setFamily(key)} style={[s.metricChip, family === key && s.metricChipSelected]}><Text style={s.small}>{key === 'total' ? 'All work' : key === 'bench' ? 'Bench' : key[0].toUpperCase() + key.slice(1)}</Text></Pressable>)}</View><Eyebrow>ACCUMULATED PERFORMED VOLUME</Eyebrow><Load kg={volumeKg} unit={unit} large compact /><Text style={s.bodyCopy}>Load × reps, accumulated over your training.</Text>{progress.achieved ? <View style={s.qualifiedCard}><Eyebrow color={C.gold}>LATEST EARNED LANDMARK</Eyebrow><Text style={s.detailTitle}>{progress.achieved.compactLabel} {unit}</Text>{reference?.visibleTitle ? <Text style={s.bodyCopy}>{reference.visibleTitle}</Text> : null}{reference?.comparison ? <Text style={s.caption}>{reference.comparison.achievedCopy}</Text> : null}</View> : null}<Section title="Your volume landmarks" />{progress.milestones.filter(m => m.state === 'achieved' || m.state === 'current').map(m => <View key={m.thresholdLb} style={s.tableRow}><Icon name={m.state === 'achieved' ? 'checkmark-circle-outline' : 'ellipse-outline'} color={m.state === 'achieved' ? C.gold : C.muted} size={19} /><Text style={[s.rowTitle, s.flex]}>{m.compactLabel} {unit}</Text><Text style={s.caption}>{m.state === 'achieved' ? 'Earned' : 'Next'}</Text></View>)}<Text style={s.caption}>Muscle-group medallions remain part of this collection, with their own governed identity and accumulated evidence.</Text><Button quiet label="View the training history" icon="arrow-forward" onPress={onHistory} /></>;
}

function SessionPreview({ entry, unit, onBack, onSet }: { entry: typeof STUDY_HISTORY[number]; unit: StudyUnit; onBack: () => void; onSet: (data: Partial<SetEvidence>) => void }) {
  const [expanded, setExpanded] = useState<string[]>([]);
  const movements = STUDY_SESSION_DETAILS[entry.id];
  const recordCount = movements.reduce((sum, m) => sum + m.sets.filter(set => set.record).length, 0);
  const isoDate = `2026-${entry.date.startsWith('Sep') ? '09' : '10'}-${entry.date.split(' ')[1].padStart(2, '0')}`;
  return <><Back label="History" onPress={onBack} /><Eyebrow>COMPLETED SESSION · {entry.date.toUpperCase()}, 2026</Eyebrow><Text style={s.detailTitle}>{entry.name}</Text><Text style={s.bodyCopy}>Autumn Build · {entry.time} · {entry.sets} performed sets</Text><View style={s.sessionSummary}><View style={s.flex}><Text style={s.mediumNumber}>{entry.sets}</Text><Text style={s.caption}>Sets completed</Text></View><View style={s.flex}><Text style={s.mediumNumber}>{recordCount}</Text><Text style={s.caption}>Personal {recordCount === 1 ? 'best' : 'bests'}</Text></View><Icon name="checkmark-circle-outline" color={C.success} size={25} /></View>
    {movements.map(m => { const all = expanded.includes(m.name); const start = all ? 0 : Math.max(0, m.sets.length - 3); return <View key={m.name} style={s.sessionMovement}><Section title={m.name} detail={`${m.equipment} · ${m.sets.length} performed sets${m.assisted ? ' · assistance' : ''}`} /><View style={s.tableHead}><Text style={[s.caption, s.repCell]}>SET</Text><Text style={[s.caption, s.flex]}>{m.assisted ? 'ASSISTANCE × REPS' : 'LOAD × REPS'}</Text><Text style={s.caption}>RPE</Text></View>{m.sets.slice(start).map((set, i) => <Pressable key={i + start} testID={`study-session-set-${m.name.replace(/ /g, '-').toLowerCase()}-${i + start + 1}`} accessibilityRole="button" accessibilityLabel={`Inspect ${m.name} set ${i + start + 1}`} onPress={() => onSet({ ...set, name: m.name, date: fullDate(isoDate), session: entry.name, equipment: m.equipment, assisted: !!m.assisted, note: set.record || 'Performed set', previousKg: set.record === '5-rep best' ? 165 : m.assisted && set.record ? 35 : null })} style={[s.tableRow, !!set.record && s.bestRow]}><Text style={[s.tableValue, s.repCell]}>{i + start + 1}</Text><View style={s.flex}><Text style={s.tableValue}>{studyWeight(set.kg, unit)} {unit} × {set.reps}</Text>{set.record ? <Text style={s.bestLabel}>{set.record}</Text> : null}</View><Text style={s.tableValue}>{set.rpe}</Text><Icon name="chevron-forward" size={16} /></Pressable>)}{m.sets.length > 3 ? <Pressable accessibilityRole="button" accessibilityLabel={`${all ? 'Show last three' : 'Show all'} ${m.name} sets`} onPress={() => setExpanded(current => all ? current.filter(n => n !== m.name) : [...current, m.name])} style={s.expandSets}><Text style={s.actionText}>{all ? 'Show last 3 sets' : `Show all ${m.sets.length} sets`}</Text><Icon name={all ? 'chevron-up' : 'chevron-down'} size={16} /></Pressable> : null}</View>; })}
    <View style={s.contextNote}><Icon name="document-text-outline" color={C.teal} /><Text style={s.bodyCopy}>Every record leads back to the set you performed. Your Session keeps its original movement and equipment context.</Text></View></>;
}

function Back({ label, onPress }: { label: string; onPress: () => void }) { return <Pressable accessibilityRole="button" accessibilityLabel={`Back to ${label}`} onPress={onPress} style={s.back}><Icon name="arrow-back" size={18} /><Text style={s.backLabel}>{label}</Text></Pressable>; }

